using System.Collections.Generic;
using UnityEngine;

namespace CarMatch
{
    // Painted UI art lives in Resources/UI (generated by tools/art/render_ui.py).
    // A missing file returns null so callers fall back to the flat SpriteKit look.
    public static class UiArt
    {
        static readonly Dictionary<string, Sprite> Cache = new Dictionary<string, Sprite>();

        public static Sprite Get(string name)
        {
            Sprite sprite;
            if (Cache.TryGetValue(name, out sprite)) return sprite;
            sprite = Resources.Load<Sprite>("UI/" + name);
            if (sprite == null)
            {
                var tex = Resources.Load<Texture2D>("UI/" + name);
                if (tex != null) sprite = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 0.5f), 100f);
            }
            Cache[name] = sprite;
            return sprite;
        }
    }
}
